const sumLedgerSpendByCoords = `-- name: SumLedgerSpendByCoords :one
SELECT COALESCE(SUM(amount), 0)::bigint AS total, count(*)::bigint AS transfers
FROM billing.ledger_transfers
WHERE merchant_id = $1::uuid
  AND customer_id = $2::uuid
  AND currency = $3::text
  AND transfer_type IN ('credit_spend', 'owed_accrual')
  AND operation = $4::text
  AND source = $5::text
  AND source_id = $6::text
`

type SumLedgerSpendByCoordsParams struct {
	MerchantID uuid.UUID
	CustomerID uuid.UUID
	Currency   string
	Operation  string
	Source     string
	SourceID   string
}

type SumLedgerSpendByCoordsRow struct {
	Total     int64
	Transfers int64
}

// SumLedgerSpendByCoords: the total posted at one operation coordinate. A spend
// fans out into one credit_spend per FIFO lot drawn plus at most one
// owed_accrual, so only the sum is the operation's amount: a retry carrying a
// different amount reuses the key with a changed body.
func (q *Queries) SumLedgerSpendByCoords(ctx context.Context, arg SumLedgerSpendByCoordsParams) (SumLedgerSpendByCoordsRow, error) {
	row := q.db.QueryRow(ctx, sumLedgerSpendByCoords,
		arg.MerchantID,
		arg.CustomerID,
		arg.Currency,
		arg.Operation,
		arg.Source,
		arg.SourceID,
	)
	var i SumLedgerSpendByCoordsRow
	err := row.Scan(&i.Total, &i.Transfers)
	return i, err
}
